import hashlib
import hmac
import time
import os
import sqlite3
from contextlib import contextmanager
from threading import Lock
from flask import Flask, request, jsonify

app = Flask(__name__)

API_SECRET = os.environ.get('API_SECRET', 'default-secret-key-change-me')
DB_PATH = os.environ.get('DB_PATH', '/tmp/service.db')


class ConnectionPool:
    """Thread-safe SQLite connection pool with bounded size."""

    def __init__(self, db_path, pool_size=5):
        self._db_path = db_path
        self._pool_size = pool_size
        self._connections = []
        self._lock = Lock()
        self._initialize_db()

    def _initialize_db(self):
        conn = sqlite3.connect(self._db_path)
        conn.execute('''CREATE TABLE IF NOT EXISTS tokens (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            token_hash TEXT NOT NULL UNIQUE,
            user_id TEXT NOT NULL,
            scope TEXT NOT NULL,
            created_at REAL NOT NULL
        )''')
        conn.commit()
        conn.close()

    @contextmanager
    def get_connection(self):
        conn = self._acquire()
        try:
            yield conn
        finally:
            self._release(conn)

    def _acquire(self):
        with self._lock:
            if self._connections:
                return self._connections.pop()
        return sqlite3.connect(self._db_path)

    def _release(self, conn):
        with self._lock:
            if len(self._connections) < self._pool_size:
                self._connections.append(conn)
            else:
                conn.close()


pool = ConnectionPool(DB_PATH)


def compute_token_hash(token):
    """Compute a SHA-256 hash of the token for storage."""
    return hashlib.sha256(token.encode('utf-8')).hexdigest()


def verify_signature(message, signature):
    """Verify HMAC signature of a request message."""
    expected = hmac.new(API_SECRET.encode(), message.encode(), hashlib.sha256).hexdigest()
    return _constant_time_compare(expected, signature)


def _constant_time_compare(a, b):
    """Compare two strings in constant time to prevent timing attacks."""
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= ord(x) ^ ord(y)
    return result == 0


def validate_token(token):
    """Validate an API token against the database.

    Uses hash-based lookup to avoid timing leaks on the token value itself.
    """
    token_hash = compute_token_hash(token)

    with pool.get_connection() as conn:
        cursor = conn.execute(
            'SELECT user_id, scope, created_at FROM tokens WHERE token_hash = ?',
            (token_hash,)
        )
        row = cursor.fetchone()

    if row is None:
        return None

    user_id, scope, created_at = row
    # Token expires after 24 hours
    if time.time() - created_at > 86400:
        return None

    return {'user_id': user_id, 'scope': scope}


def authenticate_request(req):
    """Authenticate incoming request using bearer token.

    Returns user context or None if authentication fails.
    """
    auth_header = req.headers.get('Authorization', '')

    if not auth_header.startswith('Bearer '):
        return None

    token = auth_header[7:]

    # Length check for valid token format (64 hex chars)
    if len(token) != 64:
        return None

    # Validate hex format
    try:
        int(token, 16)
    except ValueError:
        return None

    return validate_token(token)


@app.route('/api/data', methods=['GET'])
def get_data():
    user_ctx = authenticate_request(request)

    if user_ctx is None:
        return jsonify({'error': 'unauthorized'}), 401

    if 'read' not in user_ctx['scope']:
        return jsonify({'error': 'forbidden'}), 403

    return jsonify({'data': 'sensitive-information', 'user': user_ctx['user_id']})


@app.route('/api/admin/revoke', methods=['POST'])
def revoke_token():
    """Admin endpoint to revoke a token."""
    admin_ctx = authenticate_request(request)

    if admin_ctx is None:
        return jsonify({'error': 'unauthorized'}), 401

    if 'admin' not in admin_ctx['scope']:
        return jsonify({'error': 'forbidden'}), 403

    body = request.get_json()
    if not body or 'token' not in body:
        return jsonify({'error': 'missing token field'}), 400

    target_hash = compute_token_hash(body['token'])

    with pool.get_connection() as conn:
        conn.execute('DELETE FROM tokens WHERE token_hash = ?', (target_hash,))
        conn.commit()

    return jsonify({'status': 'revoked'})


@app.route('/api/health', methods=['GET'])
def health_check():
    """Health check endpoint - no auth required."""
    with pool.get_connection() as conn:
        conn.execute('SELECT 1')
    return jsonify({'status': 'healthy'})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
